// Applications interaction layer. Sample mode is isolated from saved workspaces.
(()=>{
 const realLoad=load,realSave=save,baseRender=render;
 let sample=new URLSearchParams(location.search).get('demo')==='1',query='',filterStatus='all',archivedOpen=false,listScroll=0,frontEnded=null,stageFilter='',sortOrder='default';
 const sampleSource=(company,title)=>({company,title,audience:'2027校招',category:'技术',url:'',sections:[{title:'岗位说明',text:'这是界面演示岗位，未读取真实招聘信息。用于体验进程来源、列表和工作台之间的切换。'}]});
 let examples=[
 {id:'demo-a',createdAt:'2026-09-08',source:sampleSource('腾讯','后端开发工程师'),notes:'',nodes:[{id:'a1',name:'已投递',time:'2026-09-08',origin:'投递确认邮件',demo:true},{id:'a2',name:'测评',time:'2026-09-10',origin:'测评入口',demo:true},{id:'a3',name:'一面',time:'2026-09-16T14:00:00',origin:'面试邀请',demo:true}],stage:'一面'},
 {id:'demo-b',createdAt:'2026-09-05',source:sampleSource('字节跳动','AI 应用开发工程师'),notes:'',nodes:[{id:'b1',name:'已投递',time:'2026-09-05',origin:'投递回执',demo:true},{id:'b2',name:'一面',time:'2026-09-09',origin:'一面邀请',demo:true},{id:'b3',name:'二面',time:'2026-09-12',origin:'二面邀请',demo:true},{id:'b4',name:'HR 面',time:'2026-09-18T10:00:00',origin:'HR 面邀请',demo:true}],stage:'HR 面'},
 {id:'demo-c',createdAt:'2026-09-12',source:sampleSource('小米','软件开发工程师'),notes:'',stage:'准备投递'},
 {id:'demo-d',createdAt:'2026-09-01',source:sampleSource('某科技公司','算法工程师'),notes:'',closed:true,nodes:[{id:'d1',name:'已投递',time:'2026-09-01',origin:'投递确认',demo:true},{id:'d2',name:'流程结束',time:'2026-09-08',origin:'结果通知',demo:true}],stage:'流程结束'}];
 examples.push(...['产品工程师','数据分析师'].map((title,i)=>({id:'demo-ended-'+i,createdAt:'2026-09-02',source:sampleSource(i?'示例金融公司':'示例制造公司',title),notes:'',closed:true,stage:'流程结束',nodes:[{id:'end-'+i,name:'流程结束',time:'2026-09-12',origin:'结果通知',demo:true}]})));
 load=()=>sample?examples:realLoad();save=items=>{if(sample)examples=items;else realSave(items)};
 const date=t=>{const d=new Date(t);return isNaN(d)?'时间未记录':d.toLocaleDateString('zh-CN',{month:'2-digit',day:'2-digit'})+(String(t).includes('T')&&(d.getHours()||d.getMinutes())?' '+d.toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}):'')};
 const preparing=w=>!closed(w)&&!nodes(w).some(n=>n.id!=='preparation'&&!/准备投递|待投递/.test(n.name));
 const closed=w=>!!w.closed||/不通过|未通过|已结束|流程结束|已撤回/.test(w.stage||'');
 function sourceControl(n,w){if(n.demo)return `<button class="source-link" data-demo-source="${esc(n.id)}" data-owner="${esc(w.id)}">${esc(n.origin)} ↗</button>`;if(n.url){let u;try{u=new URL(n.url)}catch{}if(u&&['https:','http:'].includes(u.protocol))return `<a class="source-link" href="${esc(u.href)}" target="_blank" rel="noopener noreferrer" title="${esc(n.origin||'查看原始来源')}">${esc(n.origin||'查看原始来源')} ↗</a>`}return `<span class="source-missing">${n.id==='preparation'?'尚未投递':'未附来源链接'}</span>`}
 nodeStrip=w=>{const list=nodes(w);let currentIndex=list.map(n=>n.status!=='upcoming').lastIndexOf(true);return `<div class="evidence-track">${list.map((n,i)=>`<div class="evidence-step ${i===currentIndex?'current-step':n.status==='upcoming'?'upcoming-step':'past-step'}"><div class="step-date">${date(n.time)}</div><button class="step-title" data-node="${esc(n.id)}" data-owner="${esc(w.id)}"><span class="step-marker"></span>${esc(n.name)}</button>${sourceControl(n,w)}</div>`).join('')}</div>`};
 const palette=[['#eaf2ff','#447bdd'],['#f1edff','#8b72c9'],['#e9f5f2','#439888'],['#fff2e5','#bc8c4b'],['#fbeef2','#bb7e97'],['#ebf3f8','#618da9']];
 const tones=(()=>{try{return JSON.parse(localStorage.getItem('career-card-colors-v1')||'{}')}catch{return {}}})();
 function tone(w){if(closed(w))return ['#f0f3f8','#91a3bf'];if(preparing(w))return ['#edf8f5','#49a78f'];if(/二面|三面|HR|hr|终面/.test(nodes(w).at(-1)?.name||''))return ['#f4efff','#9770de'];return ['#edf4ff','#4e87f4']}
 function endedDeck(items){if(!items.some(w=>w.id===frontEnded))frontEnded=items[0].id;const order=[...items.filter(w=>w.id!==frontEnded),items.find(w=>w.id===frontEnded)];return `<div class="ended-deck" style="--deck-count:${order.length}">${order.map((w,i)=>`<div class="ended-layer ${i===order.length-1?'front-layer':''}" style="--layer:${i};--depth:${order.length-1-i};z-index:${i+1}">${i<order.length-1?card(w).replace('<article ','<article inert '):card(w)}${i<order.length-1?`<button class="deck-select" data-ended-front="${esc(w.id)}" aria-label="查看已结束岗位：${esc(w.source.company+' '+w.source.title)}"><span>${esc(w.source.company)} · ${esc(w.source.title)}</span><small>已结束 ↗</small></button>`:''}</div>`).join('')}</div>`}
 function companyLogo(name){if(name==='腾讯')return '<span class="logo-tencent">Tencent</span>';if(name==='小米')return '<span class="logo-mi">mi</span>';if(name==='字节跳动')return '<svg class="logo-byte" viewBox="0 0 50 50" aria-hidden="true"><path d="M9 10v29l7-3V13z" fill="#5d72ce"/><path d="M20 19v19l7 3V22z" fill="#3a54be"/><path d="M31 22v15l7-3V19z" fill="#56b6cc"/><path d="M40 9v32l6-3V12z" fill="#8bd5ce"/></svg>';return '<span class="logo-initials">'+esc(name.slice(0,2))+'</span>'}
 function card(w){const [wash,accent]=tone(w);return `<article class="application-card ${closed(w)?'closed-card':''}" style="--job-wash:${wash};--job-accent:${accent}" data-card-id="${esc(w.id)}" tabindex="0" aria-label="打开${esc(w.source.company+' '+w.source.title)}工作台"><div class="application-heading"><div class="identity"><div class="company-mark">${companyLogo(w.source.company)}</div><div><p class="company-name">${esc(w.source.company)}</p><h2>${esc(w.source.title)}</h2><small>${esc([w.source.audience,w.source.category].filter(Boolean).join(' · '))}</small><span class="job-state">${closed(w)?'流程结束':preparing(w)?'准备投递':'推进中'}</span></div></div><div class="card-actions"><button data-card-menu="${esc(w.id)}" aria-label="管理${esc(w.source.title)}">···</button><button class="workspace-entry" data-open-card="${esc(w.id)}">进入工作台 <span>↗</span></button></div></div>${nodeStrip(w)}</article>`}
 const summaryIcon=(type)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${(type==='progress'||type==='all')?'<path d="m21 3-6 18-4-8-8-4zM11 13 21 3"/>':type==='preparing'?'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>':'<circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/>'}</svg>`;
 const currentStage=w=>closed(w)?'流程结束':preparing(w)?'准备投递':nodes(w).at(-1)?.name||w.stage||'未记录';
 function stageRank(w){const s=currentStage(w);if(/准备投递|待投递/.test(s))return 0;if(/已投递|提交|投递成功/.test(s))return 10;if(/简历|筛选/.test(s))return 20;if(/测评|笔试/.test(s))return 30;if(/HR|hr|终面/.test(s))return 70;if(/一面|第一轮/.test(s))return 40;if(/二面|第二轮/.test(s))return 50;if(/三面|第三轮/.test(s))return 60;if(/offer|Offer|意向/.test(s))return 80;if(closed(w))return 90;return null}
 function sortJobs(items){if(sortOrder==='default')return items;const time=(w,key)=>{const t=new Date(key==='created'?w.createdAt:nodes(w).at(-1)?.time).getTime();return Number.isFinite(t)?t:null};return items.sort((a,b)=>{const stage=sortOrder.startsWith('stage'),key=sortOrder.startsWith('created')?'created':'node',av=stage?stageRank(a):time(a,key),bv=stage?stageRank(b):time(b,key);if(av===null||bv===null)return av===bv?0:av===null?1:-1;return (av-bv)*(sortOrder.endsWith('new')||sortOrder==='stage-late'?-1:1)})}
 function sortButton(kind){const active=kind==='time'?sortOrder.startsWith('node'):sortOrder.startsWith('stage');const asc=sortOrder==='node-old'||sortOrder==='stage-early';const name=kind==='time'?'按当前节点时间':'按进程';return `<button class="direct-sort ${active?'sort-active':''}" data-direct-sort="${kind}" aria-label="${name}排序${active?(asc?'：升序':'：降序'):''}" title="${name}，${active?(asc?'当前升序，点击恢复默认':'当前降序，点击升序'):'点击降序'}" aria-pressed="${active}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${kind==='time'?'<circle cx="9" cy="10" r="6"/><path d="M9 6v4l3 2"/>':'<path d="M3 5h10M3 10h7M3 15h4"/>'}<path d="${active&&asc?'M19 20V4m-3 3 3-3 3 3':'M19 4v16m-3-3 3 3 3-3'}"/></svg></button>`}
 applications=()=>{const all=load(),active=all.filter(w=>!closed(w)),ended=all.filter(closed),waiting=active.filter(preparing),progress=active.filter(w=>!preparing(w)),match=w=>[w.source.company,w.source.title,...nodes(w).map(n=>n.name)].join(' ').toLowerCase().includes(query.toLowerCase())&&(!stageFilter||currentStage(w)===stageFilter),filtered=sortJobs((filterStatus==='ended'?[]:filterStatus==='preparing'?waiting:filterStatus==='progress'?progress:active).filter(match)),archive=['all','ended'].includes(filterStatus)?sortJobs(ended.filter(match)):[],groups=[['all','进行中',active.length,'尚未结束的岗位'],['preparing','待投递',waiting.length,'准备提交申请'],['ended','已结束',ended.length,'保留资料与记录']];app.innerHTML=`<div class="application-ribbons" aria-hidden="true"><svg viewBox="0 0 1200 260" preserveAspectRatio="none"><path d="M250 300C560 25 800-40 540 240C820-15 1110-150 1350-120"/></svg></div><div class="reference-account"><button data-reference-notice aria-label="通知"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M6 10a6 6 0 0 1 12 0v5l2 3H4l2-3zM10 21h4M12 2v2"/></svg><i></i></button><span class="reference-avatar" aria-hidden="true"></span><button data-reference-account>你好，Z ﹀</button></div><div class="top"><div><h1>我的投递</h1><p class="muted">追踪每一次投递进展，清晰掌握下一步。</p></div><div class="actions"><button data-view="market">返回岗位市场</button><button class="primary" data-view="market">＋ 寻找机会</button></div></div><section class="application-overview">${groups.map(([key,title,count,hint])=>`<button class="overview-tile ${key}" data-app-filter="${key}" aria-label="${title} ${count} 个岗位"><span class="overview-icon">${summaryIcon(key)}</span><span><b>${title}</b><span class="overview-bottom"><strong>${count}</strong><small>${hint}</small></span></span></button>`).join('')}<div class="overview-note" aria-hidden="true">更好的自己<br>从每一次投递开始<svg viewBox="0 0 90 24"><path d="M5 20Q40 3 84 5" fill="none" stroke="currentColor" stroke-width="2"/></svg></div></section><div class="application-toolbar"><div class="application-filters">${groups.map(g=>g.slice(0,3)).map(([v,t,c])=>`<button data-app-filter="${v}" class="${filterStatus===v?'selected':''}">${t} <small>${c}</small></button>`).join('')}</div><div class="application-search-tools"><input id="application-search" type="search" aria-label="搜索我的投递" placeholder="搜索公司、岗位或进程" value="${esc(query)}"><details class="sort-popover"><summary aria-label="筛选与排序" title="筛选与排序">☷</summary><div class="sort-popover-body"><label>当前进程<select id="application-stage" aria-label="按当前进程筛选"><option value="">全部当前进程</option>${[...new Set(all.map(currentStage))].map(n=>`<option value="${esc(n)}" ${stageFilter===n?'selected':''}>${esc(n)}</option>`).join('')}</select></label><label>排列顺序<select id="application-sort" aria-label="排序方式">${[['default','默认顺序'],['created-new','创建时间 · 最新在前'],['created-old','创建时间 · 最早在前'],['node-old','当前节点时间 · 从早到晚'],['node-new','当前节点时间 · 从晚到早'],['stage-early','当前进程 · 从前到后'],['stage-late','当前进程 · 从后到前']].map(([v,t])=>`<option value="${v}" ${sortOrder===v?'selected':''}>${t}</option>`).join('')}</select></label></div></details>${sortButton('time')}${sortButton('stage')}</div></div>${filterStatus!=='ended'?`<h2 class="list-section-heading">${summaryIcon('progress')}${filterStatus==='preparing'?'待投递':filterStatus==='progress'?'推进中':'进行中'} <span>（${filtered.length}）</span></h2><div class="application-list">${filtered.map(card).join('')||'<div class="panel empty"><h3>没有匹配的岗位</h3><p>试试其他筛选条件，或去岗位市场看看。</p></div>'}</div>`:''}${archive.length?`<section class="ended-section"><button class="ended-heading" data-toggle-ended aria-expanded="${archivedOpen}"><span>${summaryIcon('ended')} 已结束（${archive.length}）</span><span>${archivedOpen?'收起叠放 ↑':'展开全部 ↓'}</span></button>${archivedOpen?`<div class="application-list">${archive.map(card).join('')}</div>`:endedDeck(archive)}</section>`:filterStatus==='ended'?'<div class="panel empty">没有匹配的已结束岗位</div>':''}<div class="applications-foot"><span>${sample?'示例模式 · 不影响你的岗位记录':'本地保存 · 仅展示已记录的进程'}</span><button data-app-demo>${sample?'返回我的岗位':'查看示例效果'}</button></div>`};
 render=()=>{baseRender();const url=new URL(location.href);url.searchParams.set('view',view);if(sample)url.searchParams.set('demo','1');else url.searchParams.delete('demo');history.replaceState(null,'',url);if(view==='workspace'){const w=load().find(x=>x.id===current);if(w){const [wash,accent]=tone(w);const panel=app.querySelector('.process-panel');panel?.style.setProperty('--job-wash',wash);panel?.style.setProperty('--job-accent',accent)}}document.body.classList.toggle('applications-view',view==='applications');if(view==='applications')app.querySelector('.dock')?.remove();if(view==='workspace'&&sample){const linkButton=app.querySelector('[data-flow="application-link"]');if(linkButton)linkButton.remove();app.querySelector('.top').insertAdjacentHTML('afterend','<div class="sample-notice">示例工作台 · 不对应真实投递，来源仅为演示。</div>');app.querySelectorAll('.workspace-grid a').forEach(a=>{if(a.getAttribute('href')==='')a.remove()})}};
 async function enter(id){listScroll=window.scrollY;const c=document.querySelector(`[data-card-id="${CSS.escape(id)}"]`);if(c)c.style.viewTransitionName='active-job';const update=()=>{current=id;view='workspace';render();const target=app.querySelector('.process-panel');if(target)target.style.viewTransitionName='active-job';window.scrollTo(0,0)};if(document.startViewTransition&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const t=document.startViewTransition(update);try{await t.finished}catch{}app.querySelector('.process-panel')?.style.removeProperty('view-transition-name')}else update()}
 function back(){const update=()=>{view='applications';render();window.scrollTo(0,listScroll)};if(document.startViewTransition&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const panel=app.querySelector('.process-panel');if(panel)panel.style.viewTransitionName='active-job';const t=document.startViewTransition(()=>{update();const card=app.querySelector(`[data-card-id="${CSS.escape(current)}"]`);if(card)card.style.viewTransitionName='active-job'});t.finished.finally(()=>app.querySelector('[data-card-id][style]')?.style.removeProperty('view-transition-name'))}else update()}
 document.addEventListener('change',e=>{if(e.target.id==='application-stage'){stageFilter=e.target.value;render()}if(e.target.id==='application-sort'){sortOrder=e.target.value;render()}});
 document.addEventListener('input',e=>{if(e.target.id!=='application-search')return;query=e.target.value;const p=e.target.selectionStart;applications();const input=document.querySelector('#application-search');input.focus();try{input.setSelectionRange(p,p)}catch{}});
 document.addEventListener('keydown',e=>{const c=e.target.closest('[data-card-id]');if(c&&e.target===c&&['Enter',' '].includes(e.key)){e.preventDefault();enter(c.dataset.cardId)}});
 document.addEventListener('click',e=>{const b=e.target.closest('button'),c=e.target.closest('[data-card-id]');const take=()=>{e.preventDefault();e.stopImmediatePropagation()};if(b?.dataset.view==='market'&&sample){sample=false;current=null;return}if(b?.hasAttribute('data-reference-notice')){take();show('通知','<p class="muted">当前没有新的通知。</p>');return}if(b?.hasAttribute('data-reference-account')){take();show('预览账户','<p class="muted">这是界面预览中的账户展示，尚未接入账户服务。</p>');return}if(b?.dataset.directSort){take();sortOrder=b.dataset.directSort==='time'?(sortOrder==='node-new'?'node-old':sortOrder==='node-old'?'default':'node-new'):(sortOrder==='stage-late'?'stage-early':sortOrder==='stage-early'?'default':'stage-late');frontEnded=null;render();return}if(b?.dataset.endedFront){take();frontEnded=b.dataset.endedFront;render();return}if(b?.hasAttribute('data-app-demo')){take();sample=!sample;query='';stageFilter='';sortOrder='default';filterStatus='all';archivedOpen=false;render();return}if(b?.dataset.appFilter){take();filterStatus=b.dataset.appFilter;render();return}if(b?.hasAttribute('data-toggle-ended')){take();archivedOpen=!archivedOpen;render();return}if(b?.dataset.demoSource){take();const w=load().find(w=>w.id===b.dataset.owner),n=nodes(w).find(n=>n.id===b.dataset.demoSource);show(n.origin,`<div class="sample-notice">示例来源预览，不是真实公司邮件或测评链接。</div><dl class="facts"><dt>岗位</dt><dd>${esc(w.source.company+' · '+w.source.title)}</dd><dt>对应节点</dt><dd>${esc(n.name)}</dd><dt>记录时间</dt><dd>${date(n.time)}</dd></dl><p>正式使用时，这里直接打开此节点保存的邮件、测评页面或面试邀请链接。</p>`);return}if(b?.dataset.cardMenu){take();const w=load().find(w=>w.id===b.dataset.cardMenu);show('管理岗位',`<p>${esc(w.source.company+' · '+w.source.title)}</p><div class="actions" style="margin-top:20px"><button data-app-update="${esc(w.id)}">记录进程</button><button data-app-close="${esc(w.id)}">${closed(w)?'恢复到进行中':'结束此岗位流程'}</button></div><p class="helper muted">结束后收纳在列表底部，资料和历史进程保留。</p>`);return}if(b?.dataset.appUpdate){take();current=b.dataset.appUpdate;newNode();return}if(b?.dataset.appClose){take();const items=load(),w=items.find(w=>w.id===b.dataset.appClose);w.closed=!closed(w);if(!w.closed&&/不通过|未通过|已结束|流程结束|已撤回/.test(w.stage||''))w.stage='重新跟进';save(items);modal.close();render();return}if(view==='workspace'&&b?.dataset.view==='applications'){take();back();return}if(b?.dataset.openCard){take();enter(b.dataset.openCard);return}if(c&&!e.target.closest('button,a,input,textarea')){take();enter(c.dataset.cardId)}},true);
 if(new URLSearchParams(location.search).get('view')==='applications')view='applications';
 render();
})();
